import csv

def max_row_by_column(filepath: str, column: str) -> dict | None:
    with open(filepath, newline='') as f:
        reader = csv.DictReader(f)
        if column not in reader.fieldnames:
            raise ValueError(f"Column '{column}' not found. Available: {reader.fieldnames}")
        max_row = None
        max_val = None
        for row in reader:
            val = row[column].strip()
            if val == '':
                continue
            try:
                num = float(val)
            except ValueError:
                continue
            if max_val is None or num > max_val:
                max_val = num
                max_row = row
        return max_row
